using System;
using FiresCore.Logging;
using UnityEngine;

namespace VerdantsAscent
{
    // FiresTossinShade's console banners, rendered through the shared Banner engine.
    //
    //   PrintBig()  → sun over ocean waves with the FIRES TOSSIN SHADE brand.
    //                 Fires at the very top of Awake as the load announcement.
    //   Print()     → compact sun-and-waves over a status frame ("SHADERS
    //                 LIVE"). Fires once when ZNetScene is up.
    //
    // Art generated by Tools\gen_fires_banner.ps1 (spec: FiresTossinShade).
    // Color zones: sun (Yellow/DarkYellow), swell band (Cyan/DarkCyan),
    // deep water (Blue/DarkCyan), brand (Cyan/White), seabed (DarkGray).
    internal static class FiresTossinShadeBanner
    {
        private static bool s_compactPrinted;

        public static void PrintBig()
        {
            try
            {
                EmitHeader("Fires Tossin Shade Loading...");
                Banner.Print(ToSegments(s_bigLines));
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"[FiresTossinShade] Big banner failed: {ex.Message}");
            }
        }

        public static void Print()
        {
            if (s_compactPrinted) return;
            s_compactPrinted = true;
            try
            {
                EmitHeader("Fires Tossin Shade Loaded.");
                Banner.Print(s_compactLines);
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"[FiresTossinShade] Compact banner failed: {ex.Message}");
            }
        }

        // Routes the one-line header through the plugin's BepInEx log source
        // (not Debug.Log) so it prints once, colored by the shared color patch,
        // without a raw white stdout duplicate.
        private static void EmitHeader(string text)
        {
            if (FiresTossinShade.Log != null) FiresTossinShade.Log.LogInfo(text);
            else Debug.Log($"[FiresTossinShade] {text}");
        }

        private static Banner.Segment[][] ToSegments((string text, ConsoleColor color)[] lines)
        {
            var result = new Banner.Segment[lines.Length][];
            for (int i = 0; i < lines.Length; i++)
                result[i] = new[] { new Banner.Segment(lines[i].text, lines[i].color) };
            return result;
        }

        // Compact banner — sun over waves above a status frame. 31-char frame
        // body (3 lead + ╔ + 26 ═ + ╗); 🌊 is a surrogate pair, but the console
        // ADVANCES ONE column for it (no VS16), however wide the font paints the glyph, so this row pads it as one cell.
        private static readonly Banner.Segment[][] s_compactLines =
        {
            new[] { new Banner.Segment("               \\ │ /",         ConsoleColor.Yellow) },
            new[]
            {
                new Banner.Segment("             ─ ",       ConsoleColor.Yellow),
                new Banner.Segment("(███)",                 ConsoleColor.DarkYellow),
                new Banner.Segment(" ─",                    ConsoleColor.Yellow),
            },
            new[] { new Banner.Segment("               / │ \\",         ConsoleColor.Yellow) },
            new[] { new Banner.Segment("        ≈≈~≈≈≈~≈≈≈≈~≈≈≈",       ConsoleColor.Cyan) },
            new[] { new Banner.Segment("         ~≈≈≈~≈≈≈≈~≈≈~",        ConsoleColor.DarkCyan) },
            new[] { new Banner.Segment("   ╔══════════════════════════╗", ConsoleColor.DarkGray) },
            new[]
            {
                new Banner.Segment("   ║   ",              ConsoleColor.DarkGray),
                new Banner.Segment("[",                    ConsoleColor.Gray),
                new Banner.Segment("██████████████████",   ConsoleColor.Green),
                new Banner.Segment("]",                    ConsoleColor.Gray),
                new Banner.Segment("   ║",                 ConsoleColor.DarkGray),
            },
            new[]
            {
                new Banner.Segment("   ║     ",            ConsoleColor.DarkGray),
                new Banner.Segment("🌊 SHADERS LIVE",      ConsoleColor.Cyan),
                new Banner.Segment("       ║",              ConsoleColor.DarkGray),
            },
            new[] { new Banner.Segment("   ╚══════════════════════════╝", ConsoleColor.DarkGray) },
            new[] { new Banner.Segment("    FIRES TOSSIN SHADE",       ConsoleColor.Cyan) },
            new Banner.Segment[0],
            new[] { new Banner.Segment("   Fires Tossin Shade Loaded", ConsoleColor.Magenta) },
        };

